// src/client.ts
function dataArray(result) {
  const arr = result.data;
  return Array.isArray(arr) ? arr : [];
}
function dataRecord(result) {
  const val = result.data;
  return val && typeof val === "object" && !Array.isArray(val) ? val : null;
}
function numberOrUndefined(v) {
  return typeof v === "number" ? v : void 0;
}
function stringOrUndefined(v) {
  return typeof v === "string" ? v : void 0;
}
function isRecord(v) {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}
function toSessionInfo(raw) {
  const time = isRecord(raw.time) ? raw.time : null;
  return {
    id: String(raw.id ?? ""),
    title: stringOrUndefined(raw.title),
    directory: stringOrUndefined(raw.directory),
    timeCreated: numberOrUndefined(time?.created),
    timeUpdated: numberOrUndefined(time?.updated),
    ...raw.parentID !== void 0 ? { parentID: String(raw.parentID) } : {}
  };
}
function toMessageInfo(raw, sessionID) {
  const time = isRecord(raw.time) ? raw.time : null;
  const createdAt = numberOrUndefined(time?.created) ?? numberOrUndefined(raw.time);
  const role = String(raw.role ?? "user") === "assistant" ? "assistant" : "user";
  const agent = stringOrUndefined(raw.agent);
  const model = stringOrUndefined(raw.model);
  return {
    id: String(raw.id ?? ""),
    sessionID,
    role,
    time: createdAt ?? 0,
    ...agent ? { agent } : {},
    ...model ? { model } : {}
  };
}
function toPartInfo(raw) {
  return {
    id: String(raw.id ?? ""),
    messageID: String(raw.messageID ?? ""),
    type: String(raw.type ?? "text"),
    ...typeof raw.text === "string" ? { text: raw.text } : {},
    ...(raw.toolName || raw.tool) !== void 0 ? { toolName: String(raw.toolName ?? raw.tool) } : {},
    ...(raw.toolID || raw.callID) !== void 0 ? { toolID: String(raw.toolID ?? raw.callID) } : {}
  };
}
function createClient(sdk) {
  const sess = sdk.session;
  return {
    async listSessions(args) {
      const params = {};
      if (args.limit !== void 0) params.limit = String(args.limit);
      if (args.search !== void 0) params.search = args.search;
      const result = await sess.list(
        Object.keys(params).length > 0 ? { query: params } : void 0
      );
      return dataArray(result).map(toSessionInfo);
    },
    async getSession(sessionID) {
      try {
        const result = await sess.get({ path: { id: sessionID } });
        const data = dataRecord(result);
        return data ? toSessionInfo(data) : null;
      } catch {
        return null;
      }
    },
    async getMessages(sessionID, opts) {
      const params = {};
      if (opts?.limit !== void 0) params.limit = String(opts.limit);
      const result = await sess.messages({
        path: { id: sessionID },
        query: Object.keys(params).length > 0 ? params : void 0
      });
      return dataArray(result).map((entry) => {
        const info = isRecord(entry.info) ? entry.info : entry;
        return toMessageInfo(info, sessionID);
      });
    },
    async getParts(sessionID, messageIDs) {
      const requested = new Set(messageIDs);
      const result = await sess.messages({ path: { id: sessionID } });
      const out = {};
      for (const entry of dataArray(result)) {
        const info = isRecord(entry.info) ? entry.info : entry;
        const mid = String(info.id ?? "");
        if (!requested.has(mid)) continue;
        const parts = entry.parts;
        if (Array.isArray(parts)) {
          out[mid] = parts.map(
            (p) => toPartInfo(p)
          );
        }
      }
      return out;
    }
  };
}

// src/opener.ts
function createOpener(serverUrl) {
  return {
    async open(sessionID) {
      try {
        const url = new URL("/tui/select-session", serverUrl);
        const res = await fetch(url.toString(), {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ sessionID })
        });
        if (res.ok) {
          return { success: true, message: `Opened session \`${sessionID}\`` };
        }
        let msg = `Failed to open session \`${sessionID}\``;
        try {
          const body = await res.json();
          if (body.error) msg = body.error;
        } catch {
        }
        if (res.status === 404) {
          msg = `Session \`${sessionID}\` not found`;
        } else if (res.status === 400) {
          msg = `Invalid session ID: \`${sessionID}\``;
        }
        return { success: false, message: msg };
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        return {
          success: false,
          message: `Failed to open session: ${msg}`
        };
      }
    }
  };
}

// src/tools.ts
import { tool } from "@opencode-ai/plugin";

// src/types.ts
var SessionError = class extends Error {
  constructor(message, code) {
    super(message);
    this.code = code;
    this.name = "SessionError";
  }
  code;
};

// src/core.ts
var SESSION_ID_RE = /^ses_\S+$/;
function validateSessionID(raw) {
  const trimmed = raw.trim();
  if (!trimmed.startsWith("ses_")) {
    throw new SessionError('Session ID must start with "ses_"', "invalid_id");
  }
  if (trimmed.length === 4) {
    throw new SessionError(
      "Session ID must have characters after ses_",
      "invalid_id"
    );
  }
  if (!SESSION_ID_RE.test(trimmed.split("/")[0])) {
    throw new SessionError('Session ID must start with "ses_"', "invalid_id");
  }
  return trimmed;
}
var TITLE_MAX = 60;
function formatSessionList(sessions, format = "table") {
  if (sessions.length === 0) {
    return "No sessions found.";
  }
  if (format === "json") {
    const cleaned = sessions.map((s) => {
      const out = { id: s.id };
      if (s.title !== void 0) out.title = s.title;
      if (s.directory !== void 0) out.directory = s.directory;
      out.timeCreated = s.timeCreated;
      out.timeUpdated = s.timeUpdated;
      if (s.messageCount !== void 0) out.messageCount = s.messageCount;
      return out;
    });
    return JSON.stringify(cleaned, null, 2);
  }
  const lines = [];
  lines.push("| ID | Title | Directory | Updated | Msgs |");
  lines.push("|----|-------|-----------|---------|------|");
  for (const s of sessions) {
    const title = s.title ?? "-";
    const displayTitle = title.length > TITLE_MAX ? title.slice(0, TITLE_MAX - 3) + "..." : title;
    const dir = (s.directory ?? "-").replace(/\\/g, "\\\\");
    const updated = formatTimestamp(s.timeUpdated);
    const msgs = s.messageCount !== void 0 ? String(s.messageCount) : "-";
    lines.push(`| ${s.id} | ${displayTitle} | ${dir} | ${updated} | ${msgs} |`);
  }
  return lines.join("\n");
}
var TEXT_CLIP = 1500;
function summarizeSessionContent(info, messages, parts, maxMessages) {
  const relevant = maxMessages !== void 0 && messages.length > maxMessages ? messages.slice(-maxMessages) : messages;
  const userMsgs = relevant.filter((m) => m.role === "user");
  const assistantMsgs = relevant.filter((m) => m.role === "assistant");
  let toolPartCount = 0;
  for (const msg of relevant) {
    const msgParts = parts[msg.id] ?? [];
    for (const p of msgParts) {
      if (p.type === "tool") toolPartCount++;
    }
  }
  const latestUser = userMsgs.length > 0 ? userMsgs[userMsgs.length - 1] : null;
  const latestAssistant = assistantMsgs.length > 0 ? assistantMsgs[assistantMsgs.length - 1] : null;
  const lines = [];
  lines.push(`## Session \`${info.id}\``);
  if (info.title) lines.push(`**Title**: ${info.title}`);
  if (info.directory) lines.push(`**Directory**: \`${info.directory}\``);
  lines.push(`**Created**: ${formatTimestamp(info.timeCreated)}`);
  lines.push(`**Updated**: ${formatTimestamp(info.timeUpdated)}`);
  const totalMsg = messages.length;
  lines.push(
    `**Messages**: ${totalMsg} total (${relevant.length} shown, ${userMsgs.length} user, ${assistantMsgs.length} assistant)`
  );
  if (toolPartCount > 0) {
    lines.push(`**Tool calls**: ${toolPartCount}`);
  }
  if (latestUser) {
    const userParts = parts[latestUser.id] ?? [];
    const userTexts = userParts.filter((p) => p.type === "text");
    const combined = userTexts.map((p) => p.text ?? "").join("\n");
    lines.push("");
    lines.push("### Latest User Prompt");
    lines.push(clipText(combined));
  }
  if (latestAssistant) {
    const asstParts = parts[latestAssistant.id] ?? [];
    const asstTexts = asstParts.filter((p) => p.type === "text");
    const combined = asstTexts.map((p) => p.text ?? "").join("\n");
    lines.push("");
    lines.push("### Latest Assistant Response");
    lines.push(clipText(combined));
  }
  return lines.join("\n");
}
function renderFullSession(info, messages, parts, includeParts = true) {
  const lines = [];
  lines.push(`# Session \`${info.id}\``);
  if (info.title) lines.push(`**Title**: ${info.title}`);
  if (info.directory) lines.push(`**Directory**: \`${info.directory}\``);
  lines.push(
    `**Date**: ${formatTimestamp(info.timeCreated)} -- ${formatTimestamp(info.timeUpdated)}`
  );
  lines.push(`**Messages**: ${messages.length}`);
  lines.push("");
  lines.push("---");
  lines.push("");
  if (messages.length === 0) {
    lines.push("*No messages in this session.*");
    return lines.join("\n");
  }
  for (const msg of messages) {
    const roleLabel = msg.role === "user" ? "USER" : "ASSISTANT";
    const meta = [];
    if (msg.agent) meta.push(`agent: ${msg.agent}`);
    if (msg.model) meta.push(`model: ${msg.model}`);
    const metaStr = meta.length > 0 ? ` (${meta.join(", ")})` : "";
    lines.push(`### ${roleLabel}${metaStr}`);
    lines.push(`*${new Date(msg.time).toISOString()}*`);
    lines.push("");
    const msgParts = parts[msg.id] ?? [];
    for (const p of msgParts) {
      if (p.type === "text" && p.text) {
        lines.push(p.text);
        lines.push("");
      } else if (includeParts) {
        lines.push(
          `> *[${p.type}${p.toolName ? `: ${p.toolName}` : ""}${p.toolID ? ` #${p.toolID}` : ""}]*`
        );
        lines.push("");
      }
    }
    lines.push("---");
    lines.push("");
  }
  return lines.join("\n");
}
function formatTimestamp(ms) {
  if (ms === void 0) return "-";
  const d = new Date(ms);
  return isNaN(d.getTime()) ? "-" : d.toISOString().replace("T", " ").slice(0, 19);
}
function clipText(text, maxLen = TEXT_CLIP) {
  if (text.length <= maxLen) return text;
  return text.slice(0, maxLen) + "... [clipped]";
}

// src/tools.ts
var z = tool.schema;
function createTools(client, opener) {
  const session_list = tool({
    description: "List OpenCode sessions. Returns a markdown table by default, or JSON.",
    args: {
      limit: z.number().optional(),
      search: z.string().optional(),
      format: z.enum(["table", "json"]).optional()
    },
    execute: async (args, _ctx) => {
      const sessions = await client.listSessions({
        limit: args.limit,
        search: args.search
      });
      return formatSessionList(sessions, args.format ?? "table");
    }
  });
  const session_summary = tool({
    description: "Get a concise summary of an OpenCode session: metadata, message counts, latest user prompt and assistant response.",
    args: {
      sessionID: z.string(),
      maxMessages: z.number().optional()
    },
    execute: async (args, _ctx) => {
      try {
        const id = validateSessionID(args.sessionID);
        const info = await client.getSession(id);
        if (!info) return `Session \`${id}\` not found.`;
        const msgs = await client.getMessages(id, { limit: args.maxMessages });
        const msgIDs = msgs.map((m) => m.id);
        const parts = await client.getParts(id, msgIDs);
        return summarizeSessionContent(info, msgs, parts, args.maxMessages);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        return `Error: ${msg}`;
      }
    }
  });
  const session_read = tool({
    description: "Read the full content of an OpenCode session by ID, including all messages with text parts and metadata.",
    args: {
      sessionID: z.string(),
      limit: z.number().optional(),
      includeParts: z.boolean().optional()
    },
    execute: async (args, _ctx) => {
      try {
        const id = validateSessionID(args.sessionID);
        const info = await client.getSession(id);
        if (!info) return `Session \`${id}\` not found.`;
        const msgs = await client.getMessages(id, { limit: args.limit });
        const msgIDs = msgs.map((m) => m.id);
        const parts = await client.getParts(id, msgIDs);
        return renderFullSession(info, msgs, parts, args.includeParts !== false);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        return `Error: ${msg}`;
      }
    }
  });
  const session_open = tool({
    description: "Open an OpenCode session by ID in the TUI. The session must exist and the TUI must be connected.",
    args: {
      sessionID: z.string()
    },
    execute: async (args, _ctx) => {
      try {
        const id = validateSessionID(args.sessionID);
        const result = await opener.open(id);
        return result.message;
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        return `Error: ${msg}`;
      }
    }
  });
  return {
    session_list,
    session_summary,
    session_read,
    session_open
  };
}

// src/index.ts
async function server(input) {
  const client = createClient(input.client);
  const opener = createOpener(input.serverUrl);
  const tools = createTools(client, opener);
  return {
    tool: {
      session_list: tools.session_list,
      session_summary: tools.session_summary,
      session_read: tools.session_read,
      session_open: tools.session_open
    }
  };
}
var index_default = {
  id: "opencode-session-manager",
  server
};
export {
  index_default as default
};
